package cn.vie.vibe.gallery.application;
import cn.vie.vibe.gallery.domain.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import java.io.InputStream; import java.io.ByteArrayInputStream; import java.util.UUID;
@Component public class PhotoProcessingWorker { private final PhotoProcessingTaskRepository tasks; private final PhotoRepository photos; private final StorageObjectRepository objects; private final ObjectStoragePort storage; private final ThumbnailProcessor thumbnails; public PhotoProcessingWorker(PhotoProcessingTaskRepository t,PhotoRepository p,StorageObjectRepository o,ObjectStoragePort s,ThumbnailProcessor h){tasks=t;photos=p;objects=o;storage=s;thumbnails=h;}
 @Scheduled(fixedDelayString="${gallery.processing.poll-interval:5000}") public void processOne(){tasks.claimNext().ifPresent(this::process);}
 private void process(PhotoProcessingTask task){try{StorageObject object=objects.findById(task.tenantId(),photos.findById(task.tenantId(),task.photoId()).orElseThrow().storageObjectId()).orElseThrow(); try(InputStream in=storage.get(object.objectKey())){ThumbnailProcessor.ThumbnailResult r=thumbnails.create(object.mimeType(),in);String key="tenant/"+task.tenantId()+"/photos/"+task.photoId()+"/thumbnail";storage.put(key,new ByteArrayInputStream(r.content()),r.contentType(),r.content().length);objects.markReady(task.tenantId(),object.id(),key,r.width(),r.height());photos.updateStatus(task.tenantId(),task.photoId(),PhotoStatus.READY);tasks.succeed(task.id());}}catch(Exception e){objects.markFailed(task.tenantId(),task.photoId());photos.updateStatus(task.tenantId(),task.photoId(),PhotoStatus.FAILED);tasks.fail(task.id(),"Image processing failed",true);}}
}
